(1, 'priya@example.com', 50, 4, 55, 55, 88.25, 60.4, 64.225, 58.5333, '[\"css\", \"data analysis\", \"fastapi\", \"flask\", \"git\", \"html\", \"java\", \"javascript\", \"machine learning\", \"mongodb\", \"mysql\", \"postgresql\", \"python\", \"react\", \"rest api\", \"sql\", \"testing\"]', '[\"aws\", \"azure\", \"data analysis\", \"deep learning\", \"docker\", \"fastapi\", \"flask\", \"gcp\", \"git\", \"machine learning\", \"mysql\", \"python\", \"pytorch\", \"rest api\", \"sql\", \"tensorflow\", \"testing\", \"typescript\"]', '[\"data analysis\", \"fastapi\", \"flask\", \"git\", \"machine learning\", \"mysql\", \"python\", \"rest api\", \"sql\", \"testing\"]', '[\"aws\", \"azure\", \"deep learning\", \"docker\", \"gcp\", \"pytorch\", \"tensorflow\", \"typescript\"]', 'Backend Developer', '[{\"title\": \"Backend Developer\", \"match_percentage\": 93.75, \"reason\": \"Your resume demonstrates strong fastapi, python, sql experience relevant to Backend Developer positions.\", \"matched_skills\": [\"fastapi\", \"python\", \"sql\"], \"missing_skills\": [\"rest apis\"], \"required_skills\": [\"Python\", \"FastAPI\", \"SQL\", \"REST APIs\"], \"average_salary\": \"\\u20b99L\\u2013\\u20b918L\", \"future_demand\": \"High\"}, {\"title\": \"Full Stack Developer\", \"match_percentage\": 81.25, \"reason\": \"Your resume demonstrates strong python, sql experience relevant to Full Stack Developer positions.\", \"matched_skills\": [\"python\", \"sql\"], \"missing_skills\": [\"node.js\"], \"required_skills\": [\"React\", \"Node.js\", \"Python\", \"SQL\"], \"average_salary\": \"\\u20b910L\\u2013\\u20b920L\", \"future_demand\": \"Very High\"}, {\"title\": \"Frontend Developer\", \"match_percentage\": 75.0, \"reason\": \"Your overall technical background and problem-solving skills align well with the Frontend Developer career path.\", \"matched_skills\": [], \"missing_skills\": [], \"required_skills\": [\"React\", \"JavaScript\", \"HTML\", \"CSS\"], \"average_salary\": \"\\u20b98L\\u2013\\u20b916L\", \"future_demand\": \"High\"}]', 'AI Engineer', 'Backend Developer', '[\"Strong alignment with the required skills: data analysis, fastapi, flask, git\", \"Resume highlights practical experience in css, data analysis, fastapi, flask\"]', '[\"aws\", \"azure\", \"deep learning\", \"docker\", \"gcp\", \"pytorch\", \"tensorflow\", \"typescript\"]', '{\"immediate\": [\"Update your resume to highlight data analysis, fastapi and include keywords from data analysis.\", \"Incorporate these key skills from the job description: aws, azure, deep learning. Update your resume with projects or achievements that demonstrate these skills.\"], \"short_term\": [\"Complete an online course or certification in aws to strengthen this key competency.\", \"Build a practical project demonstrating aws and azure.\", \"Pursue learning resources aligned with Backend Developer to develop expertise.\"], \"long_term\": [\"Work toward becoming a Backend Developer by building a diverse portfolio of projects that demonstrate the required skills.\", \"Pursue relevant certifications and professional development in your target domain.\", \"Network with professionals in your target role and contribute to open-source projects to build industry credibility.\"]}', 'To be competitive for AI Engineer positions, focus on developing the high-priority skills where you currently have gaps. Your strongest areas are data analysis, fastapi, flask. Highlight these competencies prominently in your resume and interviews. Priority development areas: aws, azure, deep learning. These skills would significantly improve your candidacy for this role.', '[{\"level\": \"Current\", \"role\": \"Skill Development & Foundation\"}, {\"level\": \"3-6 Months\", \"role\": \"Junior Backend Development\"}, {\"level\": \"1-2 Years\", \"role\": \"Backend Development (Mid-level)\"}, {\"level\": \"3-5 Years\", \"role\": \"Senior Backend Development\"}, {\"level\": \"5+ Years\", \"role\": \"Backend Development Technical Lead/Architect\"}]', '[{\"title\": \"AWS Cloud Foundations\", \"platform\": \"AWS Skill Builder\", \"duration\": \"3 Weeks\", \"difficulty\": \"Beginner\", \"skill_covered\": \"AWS\", \"learning_path\": [\"Week 1: Core services\", \"Week 2: Security\", \"Week 3: Hands-on labs\"]}]', '2026-08-15 15:14:37', '2026-08-15 15:14:37');

