INSERT INTO `job_descriptions` (`id`, `user_email`, `job_title`, `company_name`, `description`, `created_at`) VALUES
(2, 'varna@gmail.com', 'Frontend Developer', '', 'We are looking for a passionate Frontend Developer to build responsive, user-friendly, and high-performance web applications. The ideal candidate should have a strong understanding of modern frontend technologies, problem-solving skills, and a passion for creating exceptional user experiences. You will work closely with designers, backend developers, and product managers to develop scalable and maintainable applications.\n\nResponsibilities\nDevelop responsive and interactive web applications using React.js.\nConvert UI/UX designs into high-quality, reusable components.\nWrite clean, maintainable, and well-documented code.\nOptimize applications for maximum speed and scalability.\nIntegrate REST APIs with frontend applications.\nDebug and fix frontend issues across different browsers and devices.\nCollaborate with backend developers and designers.\nParticipate in code reviews and follow coding best practices.\nEnsure cross-browser compatibility and mobile responsiveness.\nStay updated with the latest frontend technologies and trends.\nRequired Skills\nStrong knowledge of HTML5, CSS3, and JavaScript (ES6+)\nExperience with React.js\nKnowledge of TypeScript\nFamiliarity with Redux, Context API, or Zustand\nExperience with Tailwind CSS or Bootstrap\nUnderstanding of REST APIs and JSON\nGit and GitHub version control\nResponsive Web Design\nCross-browser compatibility\nBasic understanding of UI/UX principles\nPreferred Skills\nExperience with Next.js\nKnowledge of Vite\nFamiliarity with Framer Motion\nExperience with Material UI or Chakra UI\nBasic knowledge of Node.js and Express.js\nUnderstanding of Agile/Scrum methodologies\nEducational Qualification\nBachelor\'s degree in Computer Science, Information Technology, or a related field.\nFreshers with strong project experience are encouraged to apply.\nNice to Have\nPersonal portfolio showcasing projects.\nGitHub profile with active repositories.\nInternship experience in frontend or full-stack development.\nStrong communication and teamwork skills.\nBenefits\nCompetitive salary package\nFlexible working hours\nHealth insurance\nLearning and development opportunities\nHybrid/Remote work options\nPerformance-based bonuses\nCareer growth opportunities', '2026-07-30 15:12:24'),
(3, 'varna@gmail.com', 'UI Developer', '', 'Design, develop, and maintain responsive, high-quality web applications using React.js and Next.js \nBuild reusable components and frontend libraries for future use\nImplement server-side rendering (SSR), static site generation (SSG) and performance optimizations using Next.js\nTranslate UI/UX designs into clean, efficient, and accessible code\nEnsure cross-browser compatibility and mobile responsiveness\nIntegrate frontend applications with REST APIs / GraphQL services\nOptimize application performance, SEO, and page load times\nWrite unit tests and support automated testing frameworks\nParticipate in code reviews and enforce frontend-best practices\nExcellent communicator (written and verbal, formal and informal\nCollaborate closely with backend developers, designers, and product managers\n\nRequirements\n\nStrong expertise in React.js and Next.js \nProficiency in JavaScript (ES6+), HTML5, and CSS3\nExperience with modern styling approaches (CSS Modules, SCSS, Styled Components, Tailwind, etc.)\nSolid understanding of component-based architecture and state management\nHands-on experience with RESTful APIs\nKnowledge of browser rendering behavior and performance optimization techniques\nFamiliarity with Git and modern CI/CD workflows\nStrong problem-solving and debugging skills\nExcellent communication and collaboration abilities\nExperience in SQL Server T-SQL and Admin knowledge\nImplementation experience in Azure landscape\nWorking and integration with Azure and other components\nGood understanding of the development life cycle, working knowledge of the general mobile landscape, architectures, trends, and emerging technologies.\nExperience in working with third-party libraries and APIs\nGood contributions in GitHub or Azure DevOps preferred', '2026-08-06 11:30:31'),
(4, 'priya@example.com', 'AI Engineer', 'IBM', 'Job Title: AI Engineer\nCompany: IBM\nLocation: Hyderabad / Bengaluru / Pune\nExperience: 0–2 years\nEmployment Type: Full-time\n\nJob Summary:\nWe are looking for an enthusiastic AI Engineer to design, develop, and deploy Artificial Intelligence and Machine Learning solutions for real-world business problems. The candidate will work with software engineering and data teams to build intelligent applications using machine learning, NLP, Generative AI, and Python.\n\nKey Responsibilities:\n\nDevelop and implement Machine Learning and AI models.\nCollect, clean, preprocess, and analyze datasets.\nBuild and evaluate predictive ML models.\nDevelop NLP and Generative AI applications.\nIntegrate AI models with web applications and REST APIs.\nWork with Python libraries such as NumPy, Pandas, Scikit-learn, and TensorFlow/PyTorch.\nDesign and optimize data-processing pipelines.\nPerform model testing, evaluation, and performance improvement.\nCollaborate with software engineers, data scientists, and product teams.\nMaintain documentation and follow software development best practices.\n\nRequired Skills:\n\nStrong programming knowledge in Python.\nFundamentals of Machine Learning and Deep Learning.\nKnowledge of NLP and Generative AI/LLMs.\nUnderstanding of Data Structures and Algorithms.\nKnowledge of SQL and databases.\nFamiliarity with REST APIs and Git/GitHub.\nBasic understanding of cloud platforms such as AWS, Azure, or GCP.\nGood analytical and problem-solving skills.\n\nPreferred Skills:\n\nTensorFlow or PyTorch\nHugging Face Transformers\nLangChain or similar LLM frameworks\nComputer Vision\nRAG (Retrieval-Augmented Generation)\nDocker and cloud deployment\nExperience with FastAPI or Flask\n\nEducation:\n\nBachelor\'s degree in Computer Science, Information Technology, Artificial Intelligence, Data Science, or a related field.\n\nIdeal Candidate:\nA candidate who combines strong software-development fundamentals with practical AI/ML knowledge and is interested in building scalable, intelligent applications using modern AI technologies.', '2026-08-15 08:47:13');

