  `parsed_name` varchar(100) DEFAULT NULL,
  `parsed_email` varchar(100) DEFAULT NULL,
  `parsed_phone` varchar(20) DEFAULT NULL,
  `parsed_skills` text DEFAULT NULL,
  `parsed_college` varchar(255) DEFAULT NULL,
