CREATE TABLE `resume_analyses` (
  `id` int(11) NOT NULL,
  `user_email` varchar(100) DEFAULT NULL,
  `resume_id` int(11) DEFAULT NULL,
  `years_of_experience` float DEFAULT NULL,
  `education_level` varchar(100) DEFAULT NULL,
  `certifications_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`certifications_list`)),
  `projects_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`projects_list`)),
  `completeness_score` float DEFAULT NULL,
  `ats_friendliness_score` float DEFAULT NULL,
  `keyword_optimization_score` float DEFAULT NULL,
  `overall_quality_score` float DEFAULT NULL,
  `technical_skills` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`technical_skills`)),
  `soft_skills` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`soft_skills`)),
  `skill_categories` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`skill_categories`)),
  `weak_sections` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`weak_sections`)),
  `strengths_sections` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`strengths_sections`)),
  `improvement_suggestions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`improvement_suggestions`)),
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

